<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Может ли казначейство отказать в открытии лицевого счёта?", "acceptedAnswer": {"@type": "Answer", "text": "Да, но под словом «отказ» скрываются два механизма. Чаще всего это возврат документов из-за ошибок комплекта при проверке по приказу ФК № 44н — он исправляется повторной подачей. Реже — отказ или приостановление открытия по результатам казначейского мониторинга (статья 242.13-1 Бюджетного кодекса), где проверяют саму организацию и её руководителя."}}, {"@type": "Question", "name": "Чем возврат документов отличается от отказа по мониторингу?", "acceptedAnswer": {"@type": "Answer", "text": "Возврат — техническая мера: комплект не прошёл формальную проверку, и после исправления счёт откроют. Отказ по пункту 6 статьи 242.13-1 связан с самой организацией — стоп-перечни, замораживание средств, офшорная регистрация — и повторной подачей не лечится: нужно устранять основание. Понять сценарий можно по документу: причина возврата приходит в электронной системе подачи, меры мониторинга оформляются формами КФД 0531361 и 0531363."}}, {"@type": "Question", "name": "Какие самые частые причины возврата документов?", "acceptedAnswer": {"@type": "Answer", "text": "Отсутствие записи в Сводном реестре или Справочнике ИП и КФХ, ошибки в заявлении (код территориального органа казначейства, бюджет, код счёта), контракт не включён в реестр контрактов ЕИС, в контракте нет идентификатора государственного контракта или казначейской оговорки, недействующая усиленная квалифицированная электронная подпись, отсутствие машиночитаемой доверенности у подписанта."}}, {"@type": "Question", "name": "За что могут отказать в открытии счёта по статье 242.13-1?", "acceptedAnswer": {"@type": "Answer", "text": "Оснований четыре, и перечень закрытый: включение организации в перечень причастных к экстремизму или терроризму либо в перечни по решениям Совета Безопасности ООН; решение межведомственного координационного органа о замораживании средств; нахождение юрлица под контролем или значительным влиянием таких лиц; регистрация в офшорной зоне из перечня Минфина. Для добросовестной российской организации с прозрачной структурой это редкие основания."}}, {"@type": "Question", "name": "За что приостанавливают открытие лицевого счёта?", "acceptedAnswer": {"@type": "Answer", "text": "Оснований два (пункт 7 статьи 242.13-1 БК): руководитель организации включён в реестр дисквалифицированных лиц либо есть информация о банкротстве юридического лица или индивидуального предпринимателя. Приостановление — пауза, а не запрет: дальше судьбу счёта определяет заказчик."}}, {"@type": "Question", "name": "Заказчик не отвечает на уведомление о приостановлении. Что будет со счётом?", "acceptedAnswer": {"@type": "Answer", "text": "Счёт откроют. По пункту 12 Правил казначейского мониторинга (постановление № 2483) при непредставлении заказчиком решения территориальный орган казначейства открывает лицевой счёт. Молчание заказчика трактуется в пользу исполнителя, поэтому приостановление не превращается в отказ автоматически."}}, {"@type": "Question", "name": "Распространяются ли отказ и приостановление на поставщиков по госконтрактам?", "acceptedAnswer": {"@type": "Answer", "text": "Нет. И в пункте 6, и в пункте 7 статьи 242.13-1 прямо записано: меры не применяются к поставщикам (подрядчикам, исполнителям) по государственным и муниципальным контрактам. Логика в том, что поставщик уже прошёл проверку на этапе закупки по статье 31 закона № 44-ФЗ. Если подрядчику по госконтракту «отказали», почти наверняка это технический возврат документов, а не мера мониторинга."}}, {"@type": "Question", "name": "Как быстро откроют счёт после исправления ошибок?", "acceptedAnswer": {"@type": "Answer", "text": "При корректном комплекте раздел лицевого счёта по государственному контракту территориальный орган казначейства открывает, как правило, не позднее следующего рабочего дня после подачи. Количество повторных подач не ограничено. Чтобы не зависеть от сроков вовсе, номер счёта можно зарезервировать заранее — резерв действует до шести месяцев."}}, {"@type": "Question", "name": "Кому нужна машиночитаемая доверенность при открытии счёта?", "acceptedAnswer": {"@type": "Answer", "text": "Всем, у кого документы подписывает не руководитель организации. С 17 марта 2025 года действует электронный порядок (приказ ФК № 22н): комплект формируется в ГИИС «Электронный бюджет» или в ЕИС и подписывается усиленной квалифицированной электронной подписью, а полномочия подписанта-неруководителя подтверждаются машиночитаемой доверенностью по закону № 63-ФЗ. Её отсутствие — одна из частых причин возврата."}}, {"@type": "Question", "name": "Можно ли обжаловать отказ в открытии лицевого счёта?", "acceptedAnswer": {"@type": "Answer", "text": "Да: решения и действия территориальных органов казначейства обжалуются в вышестоящий орган Федерального казначейства или в арбитражный суд. Обжалование имеет смысл при ошибочном применении основания — например, совпадении наименований с фигурантом перечня или когда руководитель уже исключён из реестра дисквалифицированных. Если основание реальное, продуктивнее устранять его, а не спорить."}}, {"@type": "Question", "name": "Что происходит после открытия счёта, если открытие приостанавливали?", "acceptedAnswer": {"@type": "Answer", "text": "Счёт работает в обычном режиме, но по пункту 14 статьи 242.13-1 Федеральное казначейство информирует органы финансового мониторинга об открытии счёта после приостановления, а также об операциях свыше 50 млн рублей и переводах на банковские счета свыше 1 млн рублей при исполнении контракта. Платёжную дисциплину на таком счёте стоит держать особенно строго."}}, {"@type": "Question", "name": "Что изменится в казначейском мониторинге с 1 сентября 2026 года?", "acceptedAnswer": {"@type": "Answer", "text": "С 01.09.2026 статья 242.13-1 Бюджетного кодекса излагается в новой редакции — её установил Федеральный закон от 24.06.2025 № 158-ФЗ. Институт мониторинга сохраняется, но формулировки оснований и процедур стоит сверять с новой редакцией и актуальной версией Правил № 2483 на дату вашей подачи документов."}}]}
</script>
<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "HowTo", "name": "Что делать при отказе в открытии лицевого счёта в казначействе", "inLanguage": "ru-RU", "step": [{"@type": "HowToStep", "position": 1, "name": "Определить сценарий", "text": "Прочитать полученный документ: причина возврата в ГИИС «Электронный бюджет» или ЕИС — технический возврат по приказу № 44н; уведомление по форме КФД 0531361 или 0531363 — мера казначейского мониторинга по статье 242.13-1 БК."}, {"@type": "HowToStep", "position": 2, "name": "Установить точную причину", "text": "При возврате — сверить замечание с комплектом (Сводный реестр, реквизиты заявления, реестр контрактов, подпись, доверенность); при мере мониторинга — определить основание из пунктов 6–7 статьи 242.13-1."}, {"@type": "HowToStep", "position": 3, "name": "Исправить комплект при возврате", "text": "Устранить замечание и перепроверить остальные типовые причины: запись в Сводном реестре, идентификатор государственного контракта и казначейская оговорка в контракте, действующая усиленная квалифицированная электронная подпись, машиночитаемая доверенность."}, {"@type": "HowToStep", "position": 4, "name": "Задействовать заказчика при приостановлении", "text": "Направить заказчику пояснения и документы (смена руководителя, статус банкротного дела), просить оформить решение об открытии; если решение не представлено — счёт открывается по пункту 12 Правил № 2483."}, {"@type": "HowToStep", "position": 5, "name": "Подать документы повторно", "text": "Сформировать комплект заново в той же системе и подать; при корректном комплекте раздел лицевого счёта по контракту открывается, как правило, не позднее следующего рабочего дня."}, {"@type": "HowToStep", "position": 6, "name": "Проконтролировать результат", "text": "Получить выписку с реквизитами счёта, передать их заказчику для расчётов; после открытия соблюдать платёжную дисциплину — счёт после приостановления находится под информированием органов финансового мониторинга."}]}
</script>
